import json

baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def build_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                m[key] = pkg['resolvedVersion']
    return m

b = build_map(baseline)
a = build_map(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key)
    av = a.get(key)
    if bv != av:
        changes.append((key[0], key[1], key[2], bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((key[0], key[1], key[2], av))

print('CHANGES:')
for c in changes:
    print(f'  {c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')

print(f'\nUNCHANGED: {len(unchanged)} packages')
"

